package com.yonlab.vision;
import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.graphics.Bitmap;import android.hardware.camera2.*;import android.net.Uri;import android.os.*;import android.text.InputFilter;import android.view.*;import android.widget.*;import android.media.*;
import org.json.*;import java.lang.ref.WeakReference;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
/** Explicit local device actions with readback, restoration and honest hardware failures. */
public final class DeviceToolsActivity extends YOnActivity {
 private static final int CAMERA=851,CAPTURE=501;private static final AtomicLong IDS=new AtomicLong(SystemClock.elapsedRealtimeNanos());private static final Handler MAIN=new Handler(Looper.getMainLooper());
 private static final BoardLedController LED=BoardLedController.GLOBAL;private static final ArrayBlockingQueue<Runnable> COMMANDS=new ArrayBlockingQueue<>(16);private static final AtomicBoolean DRAINING=new AtomicBoolean(),RESTORE=new AtomicBoolean();private static final ConcurrentHashMap<String,Boolean> TORCH_STATE=new ConcurrentHashMap<>();private static final ThreadPoolExecutor IO=new ThreadPoolExecutor(0,1,1,TimeUnit.SECONDS,new ArrayBlockingQueue<>(1),r->{Thread t=new Thread(r,"YOnDeviceTools");t.setDaemon(true);return t;},new ThreadPoolExecutor.AbortPolicy());
 private static volatile Context application;private static long torchOwner;private static AtomicBoolean torchAlive;private static String torchId;private static boolean torchOriginal;
 private TextView state,output;private EditText message;private ToneGenerator tone;private CameraManager manager;private final Handler main=new Handler(Looper.getMainLooper());private AtomicBoolean alive=new AtomicBoolean();private long owner;private boolean initialDone,pendingFlash,desiredFlash;private int toneToken;
 private final CameraManager.TorchCallback torchCallback=new CameraManager.TorchCallback(){public void onTorchModeChanged(String id,boolean on){TORCH_STATE.put(id,on);}public void onTorchModeUnavailable(String id){TORCH_STATE.remove(id);}};
 public void onCreate(Bundle saved){super.onCreate(saved);application=getApplicationContext();if(saved!=null)initialDone=saved.getBoolean("initialDone");LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(Ui.BACK);LinearLayout header=Ui.brandHeader(this,"디바이스 도구");header.addView(Ui.secondary(this,"닫기",v->finish()),new LinearLayout.LayoutParams(Ui.dp(this,72),Ui.dp(this,48)));root.addView(header);LinearLayout row=new LinearLayout(this);row.setPadding(Ui.dp(this,18),Ui.dp(this,12),Ui.dp(this,18),Ui.dp(this,18));root.addView(row,new LinearLayout.LayoutParams(-1,0,1));ScrollView scroll=new ScrollView(this);LinearLayout controls=Ui.panel(this);scroll.addView(controls);LinearLayout.LayoutParams left=new LinearLayout.LayoutParams(0,-1,1);left.rightMargin=Ui.dp(this,14);row.addView(scroll,left);LinearLayout result=Ui.panel(this);state=Ui.heading(this,"기능을 선택하세요",24);result.addView(state);output=Ui.text(this,"",22);output.setTextIsSelectable(true);result.addView(output);row.addView(result,new LinearLayout.LayoutParams(0,-1,2));message=new EditText(this);message.setHint("표시할 문장");message.setText("AXSL Vision");message.setTextColor(Ui.INK);message.setFilters(new InputFilter[]{new InputFilter.LengthFilter(2048)});controls.addView(message);controls.addView(Ui.button(this,"화면에 표시",v->action("print")),space());controls.addView(Ui.secondary(this,"알림음",v->action("sound")),space());controls.addView(Ui.secondary(this,"보드 LED 켜기",v->action("led-on")),space());controls.addView(Ui.secondary(this,"보드 LED 끄기",v->action("led-off")),space());controls.addView(Ui.secondary(this,"조명 복원",v->action("restore")),space());controls.addView(Ui.secondary(this,"플래시 켜기",v->flash(true)),space());controls.addView(Ui.secondary(this,"플래시 끄기",v->flash(false)),space());controls.addView(Ui.secondary(this,"사진 촬영",v->capture()),space());setContentView(root);if(saved!=null)message.setText(saved.getString("text","AXSL Vision"));else if(getIntent().hasExtra("text"))message.setText(getIntent().getStringExtra("text"));manager=(CameraManager)getSystemService(CAMERA_SERVICE);try{manager.registerTorchCallback(torchCallback,main);}catch(RuntimeException ignored){}}
 private LinearLayout.LayoutParams space(){LinearLayout.LayoutParams p=Ui.fill();p.topMargin=Ui.dp(this,10);return p;}
 protected void onResume(){super.onResume();owner=IDS.incrementAndGet();alive=new AtomicBoolean(true);if(!initialDone){initialDone=true;String a=getIntent().getStringExtra("action");if(a!=null)main.post(()->action(a));}}
 private void action(String action){if("print".equals(action)){String value=message.getText().toString();output.setText(value);state.setText("표시 완료");recordLater("print","DISPLAYED",new JSONObject(),"");}else if("sound".equals(action))sound();else if("led-on".equals(action)||"led-off".equals(action))board("led-on".equals(action));else if("restore".equals(action))restore();else if("torch-on".equals(action))flash(true);else if("torch-off".equals(action))flash(false);else if("camera".equals(action))capture();}
 private void sound(){releaseTone();try{tone=new ToneGenerator(AudioManager.STREAM_MUSIC,65);boolean accepted=tone.startTone(ToneGenerator.TONE_PROP_BEEP,250);state.setText(accepted?"알림음 재생":"소리를 재생할 수 없습니다");recordLater("sound",accepted?"REQUEST_ACCEPTED":"FAILED",new JSONObject().put("durationMs",250).put("startToneAccepted",accepted).put("audibilityConfirmed",false),"");int token=++toneToken;main.postDelayed(()->{if(token==toneToken)releaseTone();},350);}catch(Exception e){releaseTone();state.setText("소리를 재생할 수 없습니다");recordLater("sound","FAILED",new JSONObject(),e.getClass().getSimpleName());}}
 private void releaseTone(){toneToken++;ToneGenerator t=tone;tone=null;if(t!=null){try{t.stopTone();}catch(RuntimeException ignored){}try{t.release();}catch(RuntimeException ignored){}}}
 private void board(boolean on){final AtomicBoolean allowed=alive;final long token=owner;WeakReference<DeviceToolsActivity> view=new WeakReference<>(this);if(!enqueue(()->{BoardLed.Report result=LED.set(token,allowed,on);JSONObject details=ledJson(result);record("led-"+(on?"on":"off"),result.status,details,result.error);MAIN.post(()->{DeviceToolsActivity a=view.get();if(a!=null&&a.alive==allowed&&allowed.get()){boolean applied="APPLIED".equals(result.status);a.state.setText(applied?"보드 LED 설정 완료":result.dirtyCount>0?"조명 복원이 필요합니다":"보드 LED를 사용할 수 없습니다");a.output.setText(applied?(on?"켜짐":"꺼짐"):"");}});})){state.setText("잠시 후 다시 시도하세요");}}
 private void restore(){long token=owner;AtomicBoolean allowed=alive;WeakReference<DeviceToolsActivity> view=new WeakReference<>(this);if(!enqueue(()->{BoardLed.Report report=LED.restore(token);String error=restoreTorch(token,false);record("restore",report.status,ledJson(report),error.isEmpty()?report.error:error);MAIN.post(()->{DeviceToolsActivity a=view.get();if(a!=null&&a.alive==allowed&&allowed.get())a.state.setText(report.dirtyCount==0&&error.isEmpty()?"조명 복원 완료":"조명 복원 실패");});}))state.setText("잠시 후 다시 시도하세요");}
 private void flash(boolean on){if(checkSelfPermission(Manifest.permission.CAMERA)!=PackageManager.PERMISSION_GRANTED){pendingFlash=true;desiredFlash=on;requestPermissions(new String[]{Manifest.permission.CAMERA},CAMERA);return;}long token=owner;AtomicBoolean allowed=alive;WeakReference<DeviceToolsActivity> view=new WeakReference<>(this);if(!enqueue(()->{String state="FAILED",error="";JSONObject details=new JSONObject();try{if(!allowed.get())return;CameraManager cm=(CameraManager)application.getSystemService(CAMERA_SERVICE);String chosen=null;for(String id:cm.getCameraIdList()){CameraCharacteristics cc=cm.getCameraCharacteristics(id);if(Boolean.TRUE.equals(cc.get(CameraCharacteristics.FLASH_INFO_AVAILABLE))){chosen=id;Integer facing=cc.get(CameraCharacteristics.LENS_FACING);if(facing!=null&&facing==CameraCharacteristics.LENS_FACING_BACK)break;}}if(chosen==null)throw new IllegalStateException("no_flash");if(torchOwner!=token){String restored=restoreTorch(torchOwner,false);if(!restored.isEmpty())throw new IllegalStateException("restore_pending");Boolean original=TORCH_STATE.get(chosen);if(original==null)throw new IllegalStateException("torch_state_pending");torchId=chosen;torchOriginal=original;torchOwner=token;torchAlive=allowed;}if(!allowed.get())return;cm.setTorchMode(chosen,on);state="REQUEST_ACCEPTED";details.put("cameraId",chosen).put("requestedOn",on).put("physicalLightConfirmed",false);}catch(Exception e){error=e.getClass().getSimpleName()+":"+e.getMessage();}record("torch-"+(on?"on":"off"),state,details,error);String finalState=state;MAIN.post(()->{DeviceToolsActivity a=view.get();if(a!=null&&a.alive==allowed&&allowed.get())a.state.setText("REQUEST_ACCEPTED".equals(finalState)?"플래시 설정 완료":"플래시를 사용할 수 없습니다");});}))state.setText("잠시 후 다시 시도하세요");}
 private void capture(){try{startActivityForResult(new Intent().setClassName(this,"com.yonlab.vision.CaptureActivity"),CAPTURE);}catch(ActivityNotFoundException e){state.setText("촬영을 열 수 없습니다");}}
 protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=CAPTURE||result!=RESULT_OK||data==null)return;Uri uri=data.getData();if(uri==null){String value=data.getStringExtra("photo_uri");if(value!=null)uri=Uri.parse(value);}if(uri!=null&&"content".equals(uri.getScheme()))try{startActivity(new Intent().setClassName(this,"com.yonlab.vision.PhotoActivity").putExtra("mode","lab").setDataAndType(uri,"image/*").putExtra("input_uri",uri.toString()).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION));}catch(ActivityNotFoundException e){state.setText("사진을 열 수 없습니다");}}
 public void onRequestPermissionsResult(int request,String[] names,int[] granted){super.onRequestPermissionsResult(request,names,granted);if(request==CAMERA){boolean pending=pendingFlash;pendingFlash=false;if(pending&&granted.length>0&&granted[0]==PackageManager.PERMISSION_GRANTED)flash(desiredFlash);else state.setText("카메라 권한을 허용하세요");}}
 protected void onPause(){alive.set(false);RESTORE.set(true);drainLater();releaseTone();super.onPause();}
 protected void onDestroy(){alive.set(false);RESTORE.set(true);drainLater();releaseTone();try{manager.unregisterTorchCallback(torchCallback);}catch(RuntimeException ignored){}super.onDestroy();}
 protected void onSaveInstanceState(Bundle saved){saved.putBoolean("initialDone",initialDone);saved.putString("text",message.getText().toString());super.onSaveInstanceState(saved);}
 private static boolean enqueue(Runnable action){if(!COMMANDS.offer(action))return false;drainLater();return true;}
 private static void drainLater(){if(!DRAINING.compareAndSet(false,true))return;try{IO.execute(DeviceToolsActivity::drain);}catch(RejectedExecutionException e){DRAINING.set(false);android.util.Log.e("YOn","device_queue",e);}}
 private static void drain(){try{for(;;){if(RESTORE.getAndSet(false)){BoardLed.Report report=LED.restoreInactive();String error=restoreTorch(torchOwner,true);if(!"NO_CHANGES".equals(report.status)||!error.isEmpty())record("restore-lifecycle",report.status,ledJson(report),error.isEmpty()?report.error:error);}Runnable action=COMMANDS.poll();if(action!=null){try{action.run();}catch(RuntimeException e){android.util.Log.e("YOn","device_action",e);}if(RESTORE.get())continue;}if(COMMANDS.isEmpty()&&!RESTORE.get())break;}}finally{DRAINING.set(false);if(!COMMANDS.isEmpty()||RESTORE.get())drainLater();}}
 private static String restoreTorch(long token,boolean onlyInactive){if(torchId==null||token!=torchOwner||(onlyInactive&&torchAlive!=null&&torchAlive.get()))return "";try{CameraManager cm=(CameraManager)application.getSystemService(CAMERA_SERVICE);cm.setTorchMode(torchId,torchOriginal);torchId=null;torchAlive=null;torchOwner=0;return "";}catch(Exception e){return e.getClass().getSimpleName()+":"+e.getMessage();}}
 private static JSONObject ledJson(BoardLed.Report r){JSONObject out=new JSONObject();try{out.put("backend",r.backend).put("fallbackReason",r.fallbackReason).put("original",new JSONObject(r.original)).put("readback",new JSONObject(r.current)).put("restored",new JSONObject(r.restored)).put("pendingRestoreNodes",r.dirtyCount).put("physicalLightConfirmed",false).put("shellOrPermissionChange",false);}catch(JSONException ignored){}return out;}
 private void recordLater(String action,String state,JSONObject details,String error){enqueue(()->record(action,state,details,error));}
 private static void record(String action,String state,JSONObject details,String error){Context app=application;if(app==null)return;try{JSONObject data=new JSONObject().put("action",action).put("state",state).put("details",details).put("error",error).put("elapsedMs",SystemClock.elapsedRealtime());Records.write(app,"device-tools.json",data);Records.event(app,"device-"+action,state,data);}catch(JSONException ignored){}}
}
